; Read by BattleAct_LoadAttack.
; Also BattleRom_PcAttackAct (a struct or label of the code source).
org $CD4015
Table_CD4015:
    incbin "../../build/assets/table/Table_CD4015.bin"

; $CD:451F-$CD:45A5 (135 B), padding, probable: 135 x $00
org $CD451F
Padding_CD451F:
